  function title(text,subtitle,action=''){return `<div class="page-heading"><div><h1>${text}</h1><p>${subtitle}</p></div>${action||`<span class="date-chip">${icon('calendar')}${dayLabel(T.today())}</span>`}</div>`;}
  const btn=(text,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
  const empty=(heading,copy,action='')=>`<div class="empty">${icon('chart')}<h3>${heading}</h3><p>${copy}</p>${action}</div>`;
