    const vals=points.map(p=>p.value),lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max((hi-lo)*.18,.5),min=lo-pad,max=hi+pad,x=i=>42+i*(400/(points.length-1)),y=v=>155-(v-min)/(max-min)*125;
